'use client'

import { motion } from 'motion/react'
import { clsx } from 'clsx'
import { GlassPanel } from '@/components/ui/GlassPanel'
import { Button } from '@/components/ui/Button'
import type { LearningBlock } from '@/lib/types'

interface LearningPhaseProps {
  blocks: LearningBlock[]
  onProceed: () => void
}

function LearningBlockRenderer({ block, index }: { block: LearningBlock; index: number }) {
  return (
    <motion.div
      initial={{ opacity: 0, x: -10 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{
        type: 'spring' as const,
        stiffness: 300,
        damping: 25,
        delay: index * 0.1,
      }}
    >
      {block.type === 'text' && (
        <p
          className={clsx(
            'font-body text-starlight leading-relaxed',
            block.highlight && 'border-l-2 border-nebula pl-4 bg-nebula/5 py-2 rounded-r-lg'
          )}
        >
          {block.content}
        </p>
      )}

      {block.type === 'code' && (
        <pre
          className={clsx(
            'font-mono text-sm bg-void/50 p-4 rounded-lg',
            'border border-glass-border overflow-x-auto',
            'text-starlight'
          )}
        >
          <code>{block.content}</code>
        </pre>
      )}

      {block.type === 'stat' && (
        <div
          className={clsx(
            'border-l-2 border-terracotta pl-4 py-3 rounded-r-lg',
            'bg-terracotta/10'
          )}
        >
          <p className="font-body text-starlight font-medium">{block.content}</p>
        </div>
      )}

      {block.type === 'image' && (
        <div
          className={clsx(
            'h-48 rounded-lg border border-glass-border',
            'bg-glass flex items-center justify-center'
          )}
        >
          <span className="font-mono text-sm text-starlight-dim">
            [Image: {block.content}]
          </span>
        </div>
      )}
    </motion.div>
  )
}

export function LearningPhase({ blocks, onProceed }: LearningPhaseProps) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
      transition={{ type: 'spring' as const, stiffness: 300, damping: 25 }}
      className="w-full max-w-2xl mx-auto"
    >
      <GlassPanel padding="lg">
        <div className="space-y-6">
          {/* Section Header */}
          <h3 className="font-display text-lg text-nebula uppercase tracking-wider">
            Mission Intel
          </h3>

          {/* Scrollable Content Area */}
          <div className="max-h-[60vh] overflow-y-auto space-y-4 pr-2 scrollbar-thin">
            {blocks.length > 0 ? (
              blocks.map((block, i) => (
                <LearningBlockRenderer key={i} block={block} index={i} />
              ))
            ) : (
              <p className="font-body text-starlight-dim italic">
                No learning content available for this mission yet.
              </p>
            )}
          </div>

          {/* Proceed Button */}
          <div className="pt-2">
            <Button onClick={onProceed} variant="primary" size="lg" className="w-full">
              Proceed to Challenge
            </Button>
          </div>
        </div>
      </GlassPanel>
    </motion.div>
  )
}

'use client'

import { motion } from 'motion/react'
import { clsx } from 'clsx'
import { GlassPanel } from '@/components/ui/GlassPanel'
import { Button } from '@/components/ui/Button'
import type { Mission, StatName } from '@/lib/types'
import { STAT_LABELS, STAT_COLORS } from '@/lib/constants'

interface MissionDebriefProps {
  mission: Mission
  score: number
  onNext: () => void
  onReturn: () => void
}

function getStarCount(score: number): number {
  if (score >= 90) return 3
  if (score >= 60) return 2
  return 1
}

function Stars({ count }: { count: number }) {
  return (
    <div className="flex gap-1 text-2xl">
      {[1, 2, 3].map((i) => (
        <motion.span
          key={i}
          initial={{ opacity: 0, scale: 0 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{
            type: 'spring' as const,
            stiffness: 300,
            damping: 15,
            delay: 0.3 + i * 0.2,
          }}
          className={i <= count ? 'text-terracotta' : 'text-starlight-dim/30'}
        >
          {i <= count ? '\u2605' : '\u2606'}
        </motion.span>
      ))}
    </div>
  )
}

export function MissionDebrief({ mission, score, onNext, onReturn }: MissionDebriefProps) {
  const starCount = getStarCount(score)
  const statEntries = Object.entries(mission.statRewards) as [StatName, number][]

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
      transition={{ type: 'spring' as const, stiffness: 300, damping: 25 }}
      className="w-full max-w-2xl mx-auto"
    >
      <GlassPanel padding="lg" glow="signal">
        <div className="space-y-6">
          {/* Header */}
          <div className="text-center space-y-2">
            <h2 className="font-display text-2xl text-starlight tracking-wide">
              Mission Complete
            </h2>
            <p className="font-body text-sm text-starlight-dim">
              {mission.title}
            </p>
          </div>

          {/* Score Display */}
          <div className="flex flex-col items-center gap-3">
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{
                type: 'spring' as const,
                stiffness: 200,
                damping: 15,
                delay: 0.1,
              }}
              className={clsx(
                'text-5xl font-display tabular-nums',
                score >= 90
                  ? 'text-signal'
                  : score >= 60
                    ? 'text-nebula'
                    : 'text-terracotta'
              )}
            >
              {score}%
            </motion.div>
            <Stars count={starCount} />
          </div>

          {/* Divider */}
          <div className="h-px bg-glass-border" />

          {/* Stat Gains */}
          {statEntries.length > 0 && (
            <div className="space-y-3">
              <h3 className="font-display text-sm text-starlight-dim uppercase tracking-wider">
                Stats Gained
              </h3>
              <div className="grid grid-cols-2 gap-3">
                {statEntries.map(([stat, value], i) => (
                  <motion.div
                    key={stat}
                    initial={{ opacity: 0, x: -10 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{
                      type: 'spring' as const,
                      stiffness: 300,
                      damping: 25,
                      delay: 0.5 + i * 0.1,
                    }}
                    className={clsx(
                      'flex items-center justify-between',
                      'px-3 py-2 rounded-lg bg-glass border border-glass-border'
                    )}
                  >
                    <span
                      className="font-display text-sm uppercase tracking-wider"
                      style={{ color: STAT_COLORS[stat] }}
                    >
                      {STAT_LABELS[stat]}
                    </span>
                    <span
                      className="font-mono text-sm font-bold"
                      style={{ color: STAT_COLORS[stat] }}
                    >
                      +{value}
                    </span>
                  </motion.div>
                ))}
              </div>
            </div>
          )}

          {/* Rewards */}
          {(mission.itemReward || mission.crewReward) && (
            <div className="space-y-3">
              <h3 className="font-display text-sm text-starlight-dim uppercase tracking-wider">
                Rewards
              </h3>
              <div className="flex flex-wrap gap-3">
                {mission.itemReward && (
                  <motion.div
                    initial={{ opacity: 0, scale: 0.8 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{
                      type: 'spring' as const,
                      stiffness: 300,
                      damping: 20,
                      delay: 0.7,
                    }}
                    className={clsx(
                      'px-4 py-3 rounded-lg',
                      'bg-terracotta/10 border border-terracotta/30'
                    )}
                  >
                    <p className="font-mono text-xs text-terracotta/70 uppercase">
                      Item Acquired
                    </p>
                    <p className="font-display text-sm text-terracotta mt-1">
                      {mission.itemReward}
                    </p>
                  </motion.div>
                )}
                {mission.crewReward && (
                  <motion.div
                    initial={{ opacity: 0, scale: 0.8 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{
                      type: 'spring' as const,
                      stiffness: 300,
                      damping: 20,
                      delay: 0.8,
                    }}
                    className={clsx(
                      'px-4 py-3 rounded-lg',
                      'bg-signal/10 border border-signal/30'
                    )}
                  >
                    <p className="font-mono text-xs text-signal/70 uppercase">
                      Crew Recruited
                    </p>
                    <p className="font-display text-sm text-signal mt-1">
                      {mission.crewReward}
                    </p>
                  </motion.div>
                )}
              </div>
            </div>
          )}

          {/* Action Buttons */}
          <div className="flex gap-3 pt-2">
            <Button onClick={onReturn} variant="secondary" size="md" className="flex-1">
              Return to Planet
            </Button>
            <Button onClick={onNext} variant="primary" size="md" className="flex-1">
              Next Mission
            </Button>
          </div>
        </div>
      </GlassPanel>
    </motion.div>
  )
}

'use client'

import React, { useEffect, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import { motion } from 'motion/react'
import { clsx } from 'clsx'
import { StarfieldBackground } from '@/components/ui/StarfieldBackground'
import { GlassPanel } from '@/components/ui/GlassPanel'
import { Button } from '@/components/ui/Button'
import { useGame } from '@/lib/game-context'
import { planets } from '@/lib/data/planets'
import { getMissionsByPlanet } from '@/lib/data/missions'
import type { PlanetId, Mission, MissionStatus, ChallengeType } from '@/lib/types'

const ACT_LABELS: Record<number, string> = {
  1: 'Act I',
  2: 'Act II',
  3: 'Act III',
}

const CHALLENGE_LABELS: Record<ChallengeType, string> = {
  'prompt-duel': 'Prompt Duel',
  architect: 'Architecture',
  connect: 'Connection',
  debug: 'Debug',
  command: 'Command',
  dialogue: 'Dialogue',
}

function getMissionStatus(
  mission: Mission,
  missions: Mission[],
  missionProgress: Record<string, { status: string }>
): MissionStatus {
  // Check if this mission is completed
  const progress = missionProgress[mission.id]
  if (progress?.status === 'completed') return 'completed'
  if (progress?.status === 'in_progress') return 'in_progress'

  // First mission is always available if we're on this planet page
  if (mission.order === 1) return 'available'

  // Later missions: available if the previous mission is completed
  const prevMission = missions.find((m) => m.order === mission.order - 1)
  if (prevMission) {
    const prevProgress = missionProgress[prevMission.id]
    if (prevProgress?.status === 'completed') return 'available'
  }

  return 'locked'
}

function MissionCard({
  mission,
  status,
  onClick,
}: {
  mission: Mission
  status: MissionStatus
  onClick: () => void
}) {
  const isClickable = status === 'available' || status === 'in_progress'

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{
        type: 'spring' as const,
        stiffness: 300,
        damping: 25,
        delay: mission.order * 0.08,
      }}
    >
      <GlassPanel
        hover={isClickable}
        glow={
          status === 'in_progress'
            ? 'terracotta'
            : status === 'available'
              ? 'nebula'
              : status === 'completed'
                ? 'signal'
                : undefined
        }
        className={clsx(
          status === 'locked' && 'opacity-40 cursor-not-allowed',
          status === 'available' && 'animate-pulse-subtle'
        )}
      >
        <button
          onClick={isClickable ? onClick : undefined}
          disabled={!isClickable}
          className={clsx(
            'w-full text-left flex items-start gap-4',
            !isClickable && 'cursor-not-allowed'
          )}
          [REDACTED_PROJECT]-label={`Mission ${mission.order}: ${mission.title} - ${status}`}
        >
          {/* Mission Number */}
          <div
            className={clsx(
              'flex-shrink-0 w-10 h-10 rounded-lg flex items-center justify-center',
              'font-display text-lg',
              status === 'completed'
                ? 'bg-signal/20 text-signal border border-signal/30'
                : status === 'in_progress'
                  ? 'bg-terracotta/20 text-terracotta border border-terracotta/30'
                  : status === 'available'
                    ? 'bg-nebula/20 text-nebula border border-nebula/30'
                    : 'bg-glass text-starlight-dim border border-glass-border'
            )}
          >
            {status === 'completed' ? '\u2713' : mission.order}
          </div>

          {/* Mission Info */}
          <div className="flex-1 min-w-0 space-y-1">
            <h3
              className={clsx(
                'font-display text-base tracking-wide',
                status === 'locked' ? 'text-starlight-dim' : 'text-starlight'
              )}
            >
              {mission.title}
            </h3>
            <p className="font-body text-sm text-starlight-dim truncate">
              {mission.subtitle}
            </p>
            <span
              className={clsx(
                'inline-block font-mono text-xs px-2 py-0.5 rounded',
                'bg-glass border border-glass-border text-starlight-dim'
              )}
            >
              {CHALLENGE_LABELS[mission.challengeType]}
            </span>
          </div>

          {/* Status Indicator */}
          <div className="flex-shrink-0 mt-1">
            {status === 'completed' && (
              <span className="text-signal text-sm font-mono">Complete</span>
            )}
            {status === 'in_progress' && (
              <span className="text-terracotta text-sm font-mono">In Progress</span>
            )}
            {status === 'available' && (
              <span className="text-nebula text-sm font-mono">Ready</span>
            )}
            {status === 'locked' && (
              <span className="text-starlight-dim text-sm font-mono">Locked</span>
            )}
          </div>
        </button>
      </GlassPanel>
    </motion.div>
  )
}

export default function PlanetPage({
  params,
}: {
  params: Promise<{ planetId: string }>
}) {
  const { planetId } = React.use(params)
  const { state, loading } = useGame()
  const router = useRouter()

  const planet = useMemo(
    () => planets.find((p) => p.id === planetId),
    [planetId]
  )

  const missions = useMemo(
    () => getMissionsByPlanet(planetId),
    [planetId]
  )

  useEffect(() => {
    if (!loading && !state) router.push('/')
  }, [loading, state, router])

  if (loading || !state) return null
  if (!planet) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <p className="font-body text-starlight-dim">Planet not found.</p>
      </div>
    )
  }

  return (
    <div className="min-h-screen relative">
      <StarfieldBackground density={150} speed={0.3} />

      <div className="relative z-10 max-w-3xl mx-auto px-4 py-8 space-y-8">
        {/* Navigation */}
        <Button
          onClick={() => router.push('/starmap')}
          variant="ghost"
          size="sm"
        >
          &larr; Return to Star Map
        </Button>

        {/* Planet Header */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ type: 'spring' as const, stiffness: 300, damping: 25 }}
          className="space-y-3"
        >
          <div className="flex items-center gap-3">
            <span
              className="font-mono text-xs px-2 py-1 rounded border"
              style={{
                borderColor: `${planet.color}40`,
                backgroundColor: `${planet.color}15`,
                color: planet.color,
              }}
            >
              {ACT_LABELS[planet.act]}
            </span>
          </div>
          <h1
            className="font-display text-4xl tracking-wide"
            style={{ color: planet.color }}
          >
            {planet.name}
          </h1>
          <p className="font-display text-lg text-starlight-dim">
            {planet.subtitle}
          </p>
          <p className="font-body text-starlight/80 leading-relaxed max-w-xl">
            {planet.description}
          </p>
        </motion.div>

        {/* Divider */}
        <div className="h-px bg-glass-border" />

        {/* Mission List */}
        <div className="space-y-3">
          <h2 className="font-display text-sm text-starlight-dim uppercase tracking-wider">
            Missions ({missions.length})
          </h2>
          <div className="space-y-3">
            {missions.map((mission) => {
              const status = getMissionStatus(
                mission,
                missions,
                state.missionProgress
              )
              return (
                <MissionCard
                  key={mission.id}
                  mission={mission}
                  status={status}
                  onClick={() =>
                    router.push(
                      `/planets/${planetId}/mission/${mission.id}`
                    )
                  }
                />
              )
            })}
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import React, { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { AnimatePresence, motion } from 'motion/react'
import { clsx } from 'clsx'
import { StarfieldBackground } from '@/components/ui/StarfieldBackground'
import { GlassPanel } from '@/components/ui/GlassPanel'
import { Button } from '@/components/ui/Button'
import { MissionBriefing } from '@/components/game/MissionBriefing'
import { LearningPhase } from '@/components/game/LearningPhase'
import { MissionDebrief } from '@/components/game/MissionDebrief'
import { useGame } from '@/lib/game-context'
import { getMissionById, getMissionsByPlanet } from '@/lib/data/missions'

type Phase = 'briefing' | 'learning' | 'challenge' | 'debrief'

export default function MissionPage({
  params,
}: {
  params: Promise<{ planetId: string; missionId: string }>
}) {
  const { planetId, missionId } = React.use(params)
  const { state, loading, completeMission } = useGame()
  const router = useRouter()

  const [phase, setPhase] = useState<Phase>('briefing')
  const [score, setScore] = useState(0)

  const mission = getMissionById(missionId)

  useEffect(() => {
    if (!loading && !state) router.push('/')
  }, [loading, state, router])

  const handleChallengeComplete = useCallback(
    (finalScore: number) => {
      if (!mission) return
      setScore(finalScore)
      completeMission(
        missionId,
        finalScore,
        mission.statRewards,
        mission.itemReward,
        mission.crewReward
      )
      setPhase('debrief')
    },
    [mission, missionId, completeMission]
  )

  const handleNextMission = useCallback(() => {
    if (!mission) return
    const planetMissions = getMissionsByPlanet(planetId)
    const currentIndex = planetMissions.findIndex((m) => m.id === missionId)
    const nextMission = planetMissions[currentIndex + 1]

    if (nextMission) {
      router.push(`/planets/${planetId}/mission/${nextMission.id}`)
    } else {
      // No more missions on this planet, go back to planet page
      router.push(`/planets/${planetId}`)
    }
  }, [mission, planetId, missionId, router])

  const handleReturnToPlanet = useCallback(() => {
    router.push(`/planets/${planetId}`)
  }, [planetId, router])

  if (loading || !state) return null

  if (!mission) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <GlassPanel padding="lg">
          <div className="text-center space-y-4">
            <p className="font-body text-starlight-dim">Mission not found.</p>
            <Button onClick={handleReturnToPlanet} variant="secondary">
              Return to Planet
            </Button>
          </div>
        </GlassPanel>
      </div>
    )
  }

  return (
    <div className="min-h-screen relative">
      <StarfieldBackground density={120} speed={0.2} />

      <div className="relative z-10 min-h-screen flex flex-col items-center justify-center px-4 py-8">
        {/* Phase indicator */}
        <div className="w-full max-w-2xl mb-6">
          <div className="flex items-center justify-between px-2">
            {(['briefing', 'learning', 'challenge', 'debrief'] as Phase[]).map(
              (p, i) => (
                <div key={p} className="flex items-center">
                  <div
                    className={clsx(
                      'w-8 h-8 rounded-full flex items-center justify-center',
                      'font-mono text-xs border transition-colors',
                      phase === p
                        ? 'bg-nebula/20 border-nebula text-nebula'
                        : (['briefing', 'learning', 'challenge', 'debrief'] as Phase[]).indexOf(phase) > i
                          ? 'bg-signal/20 border-signal text-signal'
                          : 'bg-glass border-glass-border text-starlight-dim'
                    )}
                  >
                    {(['briefing', 'learning', 'challenge', 'debrief'] as Phase[]).indexOf(phase) > i
                      ? '\u2713'
                      : i + 1}
                  </div>
                  {i < 3 && (
                    <div
                      className={clsx(
                        'w-12 sm:w-20 h-px mx-1',
                        (['briefing', 'learning', 'challenge', 'debrief'] as Phase[]).indexOf(phase) > i
                          ? 'bg-signal/40'
                          : 'bg-glass-border'
                      )}
                    />
                  )}
                </div>
              )
            )}
          </div>
        </div>

        {/* Phase Content */}
        <AnimatePresence mode="wait">
          {phase === 'briefing' && (
            <MissionBriefing
              key="briefing"
              mission={mission}
              onBegin={() => setPhase('learning')}
            />
          )}

          {phase === 'learning' && (
            <LearningPhase
              key="learning"
              blocks={mission.content.learning}
              onProceed={() => setPhase('challenge')}
            />
          )}

          {phase === 'challenge' && (
            <motion.div
              key="challenge"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{
                type: 'spring' as const,
                stiffness: 300,
                damping: 25,
              }}
              className="w-full max-w-2xl mx-auto"
            >
              <GlassPanel padding="lg" glow="terracotta">
                <div className="space-y-6 text-center">
                  <h2 className="font-display text-2xl text-starlight tracking-wide">
                    Challenge
                  </h2>
                  <p className="font-body text-starlight-dim">
                    {mission.content.challenge.instructions ||
                      `Complete the ${mission.challengeType} challenge.`}
                  </p>
                  <div
                    className={clsx(
                      'inline-block px-4 py-2 rounded-lg',
                      'bg-terracotta/10 border border-terracotta/30',
                      'font-mono text-sm text-terracotta'
                    )}
                  >
                    Type: {mission.challengeType}
                  </div>
                  <p className="font-body text-xs text-starlight-dim">
                    Challenge mechanics coming soon. Use the button below to
                    simulate completion.
                  </p>
                  <Button
                    onClick={() => handleChallengeComplete(80)}
                    variant="success"
                    size="lg"
                    className="w-full"
                  >
                    Complete (Mock)
                  </Button>
                </div>
              </GlassPanel>
            </motion.div>
          )}

          {phase === 'debrief' && (
            <MissionDebrief
              key="debrief"
              mission={mission}
              score={score}
              onNext={handleNextMission}
              onReturn={handleReturnToPlanet}
            />
          )}
        </AnimatePresence>
      </div>
    </div>
  )
}
